def format_bytes(n):
    """Return a human-readable byte size string like '1.5 KB'."""
    if n < 1024:
        return f"{n} B"
    elif n < 1024**2:
        return f"{n/1024:.1f} KB"
    elif n < 1024**3:
        return f"{n/1024**2:.1f} MB"
    elif n < 1024**4:
        return f"{n/1024**3:.1f} GB"
    else:
        return f"{n/1024**4:.1f} TB"
